// Package configstore adapts the gonacos Config service to GoLab's
// immutable-revision distribution model (docs/技术方案.md §3, §5.1).
//
// Mapping:
//   - (workspace, environment) → one gonacos namespace ID (generated by the
//     platform store, never user text).
//   - group is the constant GOLAB_FLAGS.
//   - every flag/segment revision is written ONCE to an immutable dataId
//     golab.flag.<key>.r<revision> / golab.segment.<key>.r<revision>.
//   - golab.manifest points at the exact dataIds+hashes in force.
//
// Publication order and confirmation (§3): flag documents are published and
// read back FIRST; the manifest is published only after all referenced
// documents verified. Publishing is confirmed by read-back (Get + hash
// comparison), never by the write call alone. gonacos push notifications are
// left untouched — SetPushFunc/SetSyncFunc are owned by server.New and must
// not be overridden (§2); GoLab's own SSE/poll layer handles fan-out.
package configstore

import (
	"encoding/json"
	"errors"
	"fmt"

	"github.com/godeps/golab/pkg/model"
	"github.com/godeps/gonacos/pkg/config"
)

func jsonUnmarshal(data []byte, v any) error { return json.Unmarshal(data, v) }

// Group is the fixed gonacos group for all GoLab documents (§5.1).
const Group = "GOLAB_FLAGS"

// ManifestDataID is the well-known dataId every SDK subscribes to first (§3:
// 枚举问题 — Nacos ListenConfig needs a known dataId).
const ManifestDataID = "golab.manifest"

// Errors surfaced to callers (admin reconciler, SDK sync).
var (
	ErrNotFound           = errors.New("configstore: document not found")
	ErrReadbackMismatch   = errors.New("configstore: read-back verification failed")
	ErrHashMismatch       = errors.New("configstore: content hash mismatch")
	ErrIncompleteSnapshot = errors.New("configstore: manifest references missing documents")
)

// FlagDataID renders the immutable dataId of one flag revision.
func FlagDataID(key string, revision int64) string {
	return fmt.Sprintf("golab.flag.%s.r%d", key, revision)
}

// SegmentDataID renders the immutable dataId of one segment revision.
func SegmentDataID(key string, revision int64) string {
	return fmt.Sprintf("golab.segment.%s.r%d", key, revision)
}

// Store is the substrate abstraction. The production implementation is
// gonacosConfig; tests may substitute fakes, but the gonacos implementation
// itself runs against the real in-memory config service.
type Store interface {
	// PublishDoc writes immutable content and confirms by read-back.
	// Returns the dataId and the SHA-256 hex of the content.
	PublishDoc(namespaceID, dataID string, content []byte) (string, error)
	// GetDoc reads one document, returning content and SHA-256 hex.
	GetDoc(namespaceID, dataID string) ([]byte, string, error)
	// DeleteDoc removes a pruned revision (idempotent).
	DeleteDoc(namespaceID, dataID string) error
	// PublishManifest writes the manifest and confirms by read-back,
	// verifying the stored bytes re-parse and re-hash identically.
	PublishManifest(namespaceID string, m *model.Manifest) error
	// GetManifest reads and parses the current manifest.
	GetManifest(namespaceID string) (*model.Manifest, error)
	// LoadSnapshot downloads every manifest entry, verifies all hashes and
	// assembles the atomic Snapshot. Any missing/corrupt document aborts
	// with an error — callers keep their previous state (§5.2).
	LoadSnapshot(namespaceID string) (*model.Snapshot, error)
}

// gonacosConfig talks to the gonacos Config service in-process.
type gonacosConfig struct {
	cfg *config.Service
}

// NewGonacosStore wraps a gonacos Config service (from
// server.Services().Config). The service must be the one assembled by
// server.New so cluster sync/push wiring stays intact.
func NewGonacosStore(cfg *config.Service) Store {
	return &gonacosConfig{cfg: cfg}
}

func (g *gonacosConfig) PublishDoc(namespaceID, dataID string, content []byte) (string, error) {
	if len(content) == 0 {
		return "", fmt.Errorf("configstore: refusing to publish empty document %s", dataID)
	}
	hash := model.HashBytes(content)
	err := g.cfg.Publish(config.PublishRequest{
		NamespaceID: namespaceID,
		GroupName:   Group,
		DataID:      dataID,
		Content:     string(content),
		Type:        "json",
		Desc:        "golab immutable revision document",
		AppName:     "golab",
	})
	if err != nil {
		return "", fmt.Errorf("configstore: publish %s/%s: %w", namespaceID, dataID, err)
	}
	// Publish confirmation = read-back (§3: 不报告"已生效"直到读回验证).
	got, gotHash, err := g.GetDoc(namespaceID, dataID)
	if err != nil {
		return "", fmt.Errorf("%w: publish of %s not confirmed: %v", ErrReadbackMismatch, dataID, err)
	}
	if gotHash != hash || string(got) != string(content) {
		return "", fmt.Errorf("%w: %s hash %s, want %s", ErrReadbackMismatch, dataID, gotHash, hash)
	}
	return dataID, nil
}

func (g *gonacosConfig) GetDoc(namespaceID, dataID string) ([]byte, string, error) {
	item, err := g.cfg.Get(namespaceID, Group, dataID)
	if err != nil {
		if errors.Is(err, config.ErrConfigNotFound) {
			return nil, "", fmt.Errorf("%w: %s/%s", ErrNotFound, namespaceID, dataID)
		}
		return nil, "", fmt.Errorf("configstore: get %s/%s: %w", namespaceID, dataID, err)
	}
	content := []byte(item.Content)
	return content, model.HashBytes(content), nil
}

func (g *gonacosConfig) DeleteDoc(namespaceID, dataID string) error {
	err := g.cfg.Delete(namespaceID, Group, dataID)
	if err != nil && !errors.Is(err, config.ErrConfigNotFound) {
		return fmt.Errorf("configstore: delete %s/%s: %w", namespaceID, dataID, err)
	}
	return nil // idempotent
}

func (g *gonacosConfig) PublishManifest(namespaceID string, m *model.Manifest) error {
	content, err := model.CanonicalJSON(m)
	if err != nil {
		return fmt.Errorf("configstore: encode manifest: %w", err)
	}
	if _, err := g.PublishDoc(namespaceID, ManifestDataID, content); err != nil {
		return err
	}
	// Extra confirmation: the manifest must re-parse and re-hash identically.
	got, gotHash, err := g.GetDoc(namespaceID, ManifestDataID)
	if err != nil {
		return fmt.Errorf("%w: manifest not readable after publish", ErrReadbackMismatch)
	}
	if gotHash != model.HashBytes(content) {
		return fmt.Errorf("%w: manifest hash drift", ErrReadbackMismatch)
	}
	var roundtrip model.Manifest
	if err := jsonUnmarshal(got, &roundtrip); err != nil {
		return fmt.Errorf("%w: manifest does not re-parse: %v", ErrReadbackMismatch, err)
	}
	if roundtrip.Revision != m.Revision {
		return fmt.Errorf("%w: manifest revision %d, wrote %d",
			ErrReadbackMismatch, roundtrip.Revision, m.Revision)
	}
	return nil
}

func (g *gonacosConfig) GetManifest(namespaceID string) (*model.Manifest, error) {
	content, _, err := g.GetDoc(namespaceID, ManifestDataID)
	if err != nil {
		return nil, err
	}
	var m model.Manifest
	if err := jsonUnmarshal(content, &m); err != nil {
		return nil, fmt.Errorf("configstore: parse manifest: %w", err)
	}
	if m.SchemaVersion != model.SchemaVersion {
		return nil, fmt.Errorf("configstore: manifest schemaVersion %d, want %d",
			m.SchemaVersion, model.SchemaVersion)
	}
	return &m, nil
}

func (g *gonacosConfig) LoadSnapshot(namespaceID string) (*model.Snapshot, error) {
	m, err := g.GetManifest(namespaceID)
	if err != nil {
		return nil, err
	}
	snap := &model.Snapshot{
		SchemaVersion:    model.SchemaVersion,
		Workspace:        m.Workspace,
		Environment:      m.Environment,
		WorkspaceSlug:    m.WorkspaceSlug,
		EnvironmentSlug:  m.EnvironmentSlug,
		ManifestRevision: m.Revision,
		GeneratedAt:      m.GeneratedAt,
		Flags:            map[string]*model.Flag{},
		Segments:         map[string]*model.Segment{},
	}
	// Segments first: flags cross-reference them at evaluator build time.
	for _, entry := range m.Segments {
		if entry.Deleted {
			continue
		}
		content, hash, err := g.GetDoc(namespaceID, entry.DataID)
		if err != nil {
			return nil, fmt.Errorf("%w: segment %s: %v", ErrIncompleteSnapshot, entry.Key, err)
		}
		if hash != entry.Hash {
			return nil, fmt.Errorf("%w: segment %s hash %s, manifest says %s",
				ErrHashMismatch, entry.Key, hash, entry.Hash)
		}
		var seg model.Segment
		if err := jsonUnmarshal(content, &seg); err != nil {
			return nil, fmt.Errorf("configstore: parse segment %s: %w", entry.Key, err)
		}
		if seg.Key != entry.Key {
			return nil, fmt.Errorf("%w: segment document key %q, manifest entry %q",
				ErrHashMismatch, seg.Key, entry.Key)
		}
		snap.Segments[seg.Key] = &seg
	}
	for _, entry := range m.Flags {
		if entry.Deleted {
			continue
		}
		content, hash, err := g.GetDoc(namespaceID, entry.DataID)
		if err != nil {
			return nil, fmt.Errorf("%w: flag %s: %v", ErrIncompleteSnapshot, entry.Key, err)
		}
		if hash != entry.Hash {
			return nil, fmt.Errorf("%w: flag %s hash %s, manifest says %s",
				ErrHashMismatch, entry.Key, hash, entry.Hash)
		}
		var f model.Flag
		if err := jsonUnmarshal(content, &f); err != nil {
			return nil, fmt.Errorf("configstore: parse flag %s: %w", entry.Key, err)
		}
		if f.Key != entry.Key {
			return nil, fmt.Errorf("%w: flag document key %q, manifest entry %q",
				ErrHashMismatch, f.Key, entry.Key)
		}
		snap.Flags[f.Key] = &f
	}
	return snap, nil
}
